"""Sanity checks for estimation, optimisation, backtest and factor code on simulated data."""
import numpy as np
import pandas as pd
import pytest

from src import backtest as bt
from src import estimation as est
from src import factors as fm
from src import optimise as opt


@pytest.fixture(scope="module")
def sim():
    """Returns generated by a known 2-factor model, so the right answers are known."""
    rng = np.random.default_rng(0)
    T, N = 600, 6
    f = pd.DataFrame(rng.normal([0.006, 0.002], [0.045, 0.03], size=(T, 2)), columns=["F1", "F2"])
    B = rng.uniform(0.5, 1.5, size=(N, 2))
    eps = rng.normal(0, 0.03, size=(T, N))
    R = pd.DataFrame(f.to_numpy() @ B.T + eps, columns=[f"S{i}" for i in range(N)])
    return R, f, B


def test_gmv_closed_form_matches_solver(sim):
    R, _, _ = sim
    S = R.cov()
    assert np.allclose(opt.gmv_closed_form(S), opt.gmv(S), atol=1e-6)


def test_long_only_constraints(sim):
    R, _, _ = sim
    mu, S = R.mean(), R.cov()
    for w in (opt.gmv(S, long_only=True), opt.max_sharpe(mu, S, 0.001, long_only=True)):
        assert np.isclose(w.sum(), 1) and (w >= 0).all()


def test_max_sharpe_beats_random(sim):
    R, _, _ = sim
    mu, S, rf = R.mean(), R.cov(), 0.001
    best = opt.portfolio_stats(opt.max_sharpe(mu, S, rf), mu, S, rf)[2]
    cloud = opt.random_portfolios(mu, S, n=2000, rf=rf)
    assert best >= cloud["sharpe"].max() - 1e-9


def test_frontier_closed_form_matches_solver(sim):
    R, _, _ = sim
    mu, S = R.mean(), R.cov()
    targets = np.linspace(mu.min(), mu.max(), 5)
    assert np.allclose(opt.frontier(mu, S, targets)["vol"], opt.frontier_closed_form(mu, S, targets)["vol"], rtol=1e-4)


def test_max_drawdown():
    r = pd.Series([0.10, -0.50, 0.20])
    # Wealth 1.1 -> 0.55 -> 0.66; worst fall from the 1.1 peak is -50%.
    assert np.isclose(bt.max_drawdown(r), -0.5)


def test_years_needed():
    # 20% vol, +/-2% half-width: (1.96 * 0.2 / 0.02)^2 = 384.16 years.
    assert np.isclose(est.years_needed(0.20, 0.02), 384.16)


def test_regression_recovers_loadings(sim):
    R, f, B = sim
    reg = fm.multi_regression(R, f)
    # SE of each loading is about 0.03 / (0.03 * sqrt(600)) = 0.04, so allow ~3.5 SE.
    assert np.allclose(reg["betas"].to_numpy(), B, atol=0.15)


def test_grs_does_not_reject_true_model(sim):
    R, f, _ = sim
    reg = fm.multi_regression(R, f)
    _, p = fm.grs_test(reg["alpha"], reg["resid"], f)
    assert p > 0.01


def test_grs_rejects_with_alpha(sim):
    R, f, _ = sim
    R_alpha = R + 0.01  # 12% a year of alpha on every asset
    reg = fm.multi_regression(R_alpha, f)
    _, p = fm.grs_test(reg["alpha"], reg["resid"], f)
    assert p < 1e-6


def test_factor_covariance_close_to_sample(sim):
    R, f, _ = sim
    S_f, parts = fm.factor_covariance(R, f)
    assert np.allclose(S_f, R.cov(), atol=2e-4)
    avg, _ = fm.residual_correlation(parts["resid"])
    assert abs(avg) < 0.05


def test_parameter_counts_match_plan():
    pc = fm.parameter_counts()
    assert pc.loc[20, "sample"] == 210 and pc.loc[20, "factor K=3"] == 86
    assert pc.loc[500, "sample"] == 125_250 and pc.loc[500, "factor K=3"] == 2_006


def test_split_has_no_overlap():
    idx = pd.period_range("2006-01", "2025-12", freq="M")
    df = pd.DataFrame({"x": range(len(idx))}, index=idx)
    train, test = est.split_train_test(df, "2015-12")
    assert len(train) == 120 and len(test) == 120
    assert train.index.max() < test.index.min()
